[Fact]
public async Task DelayAsync_WithCancellationToken_CompletesWhenNotCanceled()
{
    // Arrange
    var delayProvider = new DelayProvider();
    var cts = new CancellationTokenSource();
    int delayMilliseconds = 100;

    // Act
    var delayTask = delayProvider.DelayAsync(delayMilliseconds, cts.Token);
    
    // Assert
    await Assert.ThrowsAsync<TimeoutException>(() => delayTask.TimeoutAfter(50));
    
    await Task.Delay(delayMilliseconds + 10); // Ensure enough time has passed
    
    Assert.True(delayTask.IsCompleted, "The delay task should complete when not canceled.");
    await Assert.ThrowsAsync<TaskCanceledException>(() => cts.CancelAfter(1).AsTask());

